<?php
require_once __DIR__.'/../../config/db.php';
class ChatModel{
 private mysqli $db; function __construct(){global $conn;$this->db=$conn;}
 private function member($u,$c){$s=$this->db->prepare("SELECT role FROM chat_members WHERE user_id=? AND conversation_id=? AND status='active'");$s->bind_param('ii',$u,$c);$s->execute();$r=$s->get_result()->fetch_assoc();if(!$r)throw new DomainException('Conversation access denied.');return $r;}
 function cleanupEmptyDiscussions(){$this->db->query("DELETE FROM chat_conversations WHERE type='contextual' AND created_at<DATE_SUB(NOW(),INTERVAL 1 HOUR) AND NOT EXISTS(SELECT 1 FROM chat_conversation_messages WHERE conversation_id=chat_conversations.id LIMIT 1)");}
 function conversations($u){$this->cleanupEmptyDiscussions();$q="SELECT c.id,c.type,COALESCE(c.name,peer.nick_name,'Conversation') name,c.description,c.status,c.last_message_at,m.body last_message,cm.role,cm.muted_at,cm.archived_at,cm.pinned_at,ctx.context_type,ctx.context_id,ctx.context_title,ctx.context_url,(SELECT COUNT(*) FROM chat_conversation_messages z WHERE z.conversation_id=c.id AND z.status='active' AND z.sender_id<>? AND z.id>COALESCE(cm.last_read_message_id,0)) unread_count FROM chat_members cm JOIN chat_conversations c ON c.id=cm.conversation_id LEFT JOIN chat_conversation_messages m ON m.id=c.last_message_id LEFT JOIN chat_contexts ctx ON ctx.conversation_id=c.id LEFT JOIN chat_members pm ON c.type='direct' AND pm.conversation_id=c.id AND pm.user_id<>? AND pm.status='active' LEFT JOIN users peer ON peer.id=pm.user_id WHERE cm.user_id=? AND cm.status='active' AND cm.archived_at IS NULL ORDER BY cm.pinned_at IS NULL,c.last_message_at DESC,c.id DESC";$s=$this->db->prepare($q);$s->bind_param('iii',$u,$u,$u);$s->execute();return $s->get_result()->fetch_all(MYSQLI_ASSOC);}
 function create($u,$d){$type=$d['type']??'direct';$ids=array_values(array_unique(array_filter(array_map('intval',$d['member_ids']??[]),fn($v)=>$v>0&&$v!==$u)));if($type==='direct'&&count($ids)!==1)throw new InvalidArgumentException('Select one user.');$pair=[$u,$ids[0]??0];sort($pair);$key=$type==='direct'?implode(':',$pair):null;$this->db->begin_transaction();try{$s=$this->db->prepare('INSERT INTO chat_conversations(type,name,description,created_by,direct_key,last_message_at) VALUES(?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)');$name=trim($d['name']??'')?:null;$desc=trim($d['description']??'')?:null;$s->bind_param('sssis',$type,$name,$desc,$u,$key);$s->execute();$id=(int)$this->db->insert_id;$all=array_unique(array_merge([$u],$ids));$add=$this->db->prepare("INSERT IGNORE INTO chat_members(conversation_id,user_id,role) VALUES(?,?,?)");foreach($all as $uid){$role=$uid===$u?'owner':'member';$add->bind_param('iis',$id,$uid,$role);$add->execute();}if($type==='contextual'){$c=$d['context']??[];$ct=$c['type']??'';$ci=(string)($c['id']??'');$title=trim($c['title']??'');$url=$c['url']??null;if(!$ct||!$ci||!$title)throw new InvalidArgumentException('Context is incomplete.');$x=$this->db->prepare('INSERT INTO chat_contexts(conversation_id,context_type,context_id,context_title,context_url) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE conversation_id=LAST_INSERT_ID(conversation_id)');$x->bind_param('issss',$id,$ct,$ci,$title,$url);$x->execute();}$this->db->commit();return ['id'=>$id];}catch(Throwable $e){$this->db->rollback();throw $e;}}
 function messages($u,$c,$before=0){$this->member($u,$c);$delivered=$this->db->prepare('UPDATE chat_members SET last_delivered_message_id=(SELECT COALESCE(MAX(id),0) FROM chat_conversation_messages WHERE conversation_id=?),last_delivered_at=NOW() WHERE conversation_id=? AND user_id=?');$delivered->bind_param('iii',$c,$c,$u);$delivered->execute();$where=$before>0?' AND m.id<?':'';$sql="SELECT m.id,m.conversation_id,m.sender_id,u.nick_name sender_name,m.type,m.body,m.reply_to_id,m.status,m.created_at,m.edited_at,r.body reply_body,r.sender_id reply_sender_id,ru.nick_name reply_sender,(SELECT COUNT(*) FROM chat_members total WHERE total.conversation_id=m.conversation_id AND total.status='active' AND total.user_id<>m.sender_id) recipient_count,(SELECT COUNT(*) FROM chat_members delivered WHERE delivered.conversation_id=m.conversation_id AND delivered.status='active' AND delivered.user_id<>m.sender_id AND COALESCE(delivered.last_delivered_message_id,0)>=m.id) delivered_count,(SELECT COUNT(*) FROM chat_members reader WHERE reader.conversation_id=m.conversation_id AND reader.status='active' AND reader.user_id<>m.sender_id AND COALESCE(reader.last_read_message_id,0)>=m.id) read_count FROM chat_conversation_messages m JOIN users u ON u.id=m.sender_id LEFT JOIN chat_conversation_messages r ON r.id=m.reply_to_id LEFT JOIN users ru ON ru.id=r.sender_id WHERE m.conversation_id=?$where ORDER BY m.id DESC LIMIT 50";$query=$this->db->prepare($sql);if($before>0)$query->bind_param('ii',$c,$before);else$query->bind_param('i',$c);$query->execute();return array_reverse($query->get_result()->fetch_all(MYSQLI_ASSOC));}
 function receiptInfo($u,$id){$q=$this->db->prepare('SELECT conversation_id,sender_id,created_at FROM chat_conversation_messages WHERE id=?');$q->bind_param('i',$id);$q->execute();$message=$q->get_result()->fetch_assoc();if(!$message)throw new InvalidArgumentException('Message not found.');$conversationId=(int)$message['conversation_id'];$this->member($u,$conversationId);if((int)$message['sender_id']!==$u)throw new DomainException('Message information is available only for messages you sent.');$s=$this->db->prepare("SELECT cm.user_id,u.nick_name,u.email,p.position_name,CASE WHEN COALESCE(cm.last_delivered_message_id,0)>=? THEN 1 ELSE 0 END delivered,CASE WHEN COALESCE(cm.last_read_message_id,0)>=? THEN 1 ELSE 0 END is_read,CASE WHEN COALESCE(cm.last_delivered_message_id,0)>=? THEN cm.last_delivered_at END delivered_at,CASE WHEN COALESCE(cm.last_read_message_id,0)>=? THEN cm.last_read_at END read_at FROM chat_members cm JOIN users u ON u.id=cm.user_id LEFT JOIN positions p ON p.id=u.position_id WHERE cm.conversation_id=? AND cm.user_id<>? AND cm.status='active' ORDER BY is_read DESC,delivered DESC,u.nick_name");$s->bind_param('iiiiii',$id,$id,$id,$id,$conversationId,$u);$s->execute();return ['sent_at'=>$message['created_at'],'recipients'=>$s->get_result()->fetch_all(MYSQLI_ASSOC)];} function send($u,$c,$d){$this->member($u,$c);$body=trim($d['body']??'');if($body===''||mb_strlen($body)>10000)throw new InvalidArgumentException('Message must contain 1 to 10,000 characters.');$client=$d['client_id']??null;$reply=(int)($d['reply_to_id']??0)?:null;$s=$this->db->prepare("INSERT INTO chat_conversation_messages(conversation_id,sender_id,client_id,body,reply_to_id) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)");$s->bind_param('iissi',$c,$u,$client,$body,$reply);$s->execute();$id=(int)$this->db->insert_id;$x=$this->db->prepare('UPDATE chat_conversations SET last_message_id=?,last_message_at=NOW() WHERE id=?');$x->bind_param('ii',$id,$c);$x->execute();$n=$this->db->prepare("INSERT IGNORE INTO chat_notifications(user_id,actor_id,conversation_id,message_id,type,title,body,destination_url,dedupe_key) SELECT user_id,?,?,?,'message','New message',LEFT(?,500),CONCAT('/dashboard/chat?conversation=',?),CONCAT('message:',? ,':',user_id) FROM chat_members WHERE conversation_id=? AND user_id<>? AND status='active' AND muted_at IS NULL");$n->bind_param('iiisiiii',$u,$c,$id,$body,$c,$id,$c,$u);$n->execute();$wake=$this->db->prepare('UPDATE chat_members SET archived_at=NULL WHERE conversation_id=? AND user_id<>?');$wake->bind_param('ii',$c,$u);$wake->execute();return ['id'=>$id,'created_at'=>date('Y-m-d H:i:s')];}
 function read($u,$c){$this->member($u,$c);$s=$this->db->prepare('UPDATE chat_members SET last_delivered_message_id=(SELECT COALESCE(MAX(id),0) FROM chat_conversation_messages WHERE conversation_id=?),last_delivered_at=NOW(),last_read_message_id=(SELECT COALESCE(MAX(id),0) FROM chat_conversation_messages WHERE conversation_id=?),last_read_at=NOW() WHERE conversation_id=? AND user_id=?');$s->bind_param('iiii',$c,$c,$c,$u);$s->execute();return true;}
 function users($u,$q){$q='%'.trim($q).'%';$s=$this->db->prepare("SELECT u.id,u.nick_name,u.email,u.employee_id,p.position_name FROM users u LEFT JOIN positions p ON p.id=u.position_id WHERE u.status='Active' AND u.id<>? AND (u.nick_name LIKE ? OR u.email LIKE ? OR CAST(u.employee_id AS CHAR) LIKE ?) ORDER BY u.nick_name LIMIT 20");$s->bind_param('isss',$u,$q,$q,$q);$s->execute();return $s->get_result()->fetch_all(MYSQLI_ASSOC);}
 function notifications($u){$s=$this->db->prepare('SELECT * FROM chat_notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$s->bind_param('i',$u);$s->execute();return $s->get_result()->fetch_all(MYSQLI_ASSOC);}
 function autoContextMembers($type,$id){$ids=[];$recordId=(int)$id;if($recordId<1)return $ids;if($type==='submission'){$q=$this->db->prepare('SELECT a.employee_id,c.created_by FROM application a LEFT JOIN candidate c ON c.id=a.candidate_id WHERE a.id=?');$q->bind_param('i',$recordId);$q->execute();$row=$q->get_result()->fetch_assoc();foreach([$row['employee_id']??0,$row['created_by']??0] as $uid)if((int)$uid>0)$ids[]=(int)$uid;}elseif($type==='candidate'){$q=$this->db->prepare('SELECT created_by FROM candidate WHERE id=?');$q->bind_param('i',$recordId);$q->execute();$row=$q->get_result()->fetch_assoc();if((int)($row['created_by']??0)>0)$ids[]=(int)$row['created_by'];$a=$this->db->prepare('SELECT DISTINCT employee_id FROM application WHERE candidate_id=? AND employee_id IS NOT NULL');$a->bind_param('i',$recordId);$a->execute();$result=$a->get_result();while($member=$result->fetch_assoc())if((int)$member['employee_id']>0)$ids[]=(int)$member['employee_id'];}return array_values(array_unique($ids));}
 function context($u,$d){$c=$d['context']??[];$type=preg_replace('/[^a-z0-9_-]/','',strtolower($c['type']??''));$id=trim((string)($c['id']??''));$title=trim($c['title']??'');if(!$type||!$id||!$title)throw new InvalidArgumentException('Context is incomplete.');$participants=array_values(array_unique(array_merge([$u],$this->autoContextMembers($type,$id),array_map('intval',$d['member_ids']??[]))));$q=$this->db->prepare('SELECT conversation_id FROM chat_contexts WHERE context_type=? AND context_id=? LIMIT 1');$q->bind_param('ss',$type,$id);$q->execute();$existing=$q->get_result()->fetch_assoc();if($existing){$cid=(int)$existing['conversation_id'];$add=$this->db->prepare("INSERT INTO chat_members(conversation_id,user_id,role,status) VALUES(?,?,'member','active') ON DUPLICATE KEY UPDATE status='active'");foreach($participants as $uid){if($uid<1)continue;$add->bind_param('ii',$cid,$uid);$add->execute();}return ['id'=>$cid,'existing'=>true];}$d['type']='contextual';$d['member_ids']=array_values(array_filter($participants,fn($uid)=>$uid!==$u));$d['context']=['type'=>$type,'id'=>$id,'title'=>$title,'url'=>$c['url']??null];return $this->create($u,$d);}
 function notificationSummary($u){$s=$this->db->prepare('SELECT COUNT(*) unread FROM chat_notifications WHERE user_id=? AND is_read=0');$s->bind_param('i',$u);$s->execute();return (int)$s->get_result()->fetch_assoc()['unread'];}
 function readNotification($u,$id){$s=$this->db->prepare('UPDATE chat_notifications SET is_read=1,read_at=COALESCE(read_at,NOW()) WHERE id=? AND user_id=?');$s->bind_param('ii',$id,$u);$s->execute();if(!$s->affected_rows){$q=$this->db->prepare('SELECT id FROM chat_notifications WHERE id=? AND user_id=?');$q->bind_param('ii',$id,$u);$q->execute();if(!$q->get_result()->fetch_assoc())throw new DomainException('Notification access denied.');}return true;}
 function readAllNotifications($u){$s=$this->db->prepare('UPDATE chat_notifications SET is_read=1,read_at=COALESCE(read_at,NOW()) WHERE user_id=? AND is_read=0');$s->bind_param('i',$u);$s->execute();return ['updated'=>$s->affected_rows];} function editMessage($u,$id,$d){$body=trim($d['body']??'');if($body===''||mb_strlen($body)>10000)throw new InvalidArgumentException('Message must contain 1 to 10,000 characters.');$q=$this->db->prepare('SELECT conversation_id,sender_id,status FROM chat_conversation_messages WHERE id=?');$q->bind_param('i',$id);$q->execute();$m=$q->get_result()->fetch_assoc();if(!$m)throw new DomainException('Message not found.');$this->member($u,(int)$m['conversation_id']);if((int)$m['sender_id']!==$u)throw new DomainException('Only the author can edit this message.');if($m['status']!=='active')throw new DomainException('Deleted messages cannot be edited.');$x=$this->db->prepare('UPDATE chat_conversation_messages SET body=?,edited_at=NOW() WHERE id=?');$x->bind_param('si',$body,$id);$x->execute();return true;}
 function deleteMessage($u,$id,$moderate=false){$q=$this->db->prepare('SELECT conversation_id,sender_id,status FROM chat_conversation_messages WHERE id=?');$q->bind_param('i',$id);$q->execute();$m=$q->get_result()->fetch_assoc();if(!$m)throw new DomainException('Message not found.');if(!$moderate){$this->member($u,(int)$m['conversation_id']);if((int)$m['sender_id']!==$u)throw new DomainException('Only the author can delete this message.');}$status=$moderate?'moderated':'deleted';$x=$this->db->prepare('UPDATE chat_conversation_messages SET body=NULL,status=?,deleted_at=NOW() WHERE id=?');$x->bind_param('si',$status,$id);$x->execute();return true;}
 function members($u,$c){$this->member($u,$c);$s=$this->db->prepare("SELECT cm.user_id,cm.role,cm.status,cm.joined_at,u.nick_name,u.email,p.position_name FROM chat_members cm JOIN users u ON u.id=cm.user_id LEFT JOIN positions p ON p.id=u.position_id WHERE cm.conversation_id=? AND cm.status='active' ORDER BY FIELD(cm.role,'owner','admin','member'),u.nick_name");$s->bind_param('i',$c);$s->execute();return $s->get_result()->fetch_all(MYSQLI_ASSOC);}
 function addMembers($u,$c,$ids){$me=$this->member($u,$c);if(!in_array($me['role'],['owner','admin'],true))throw new DomainException('Group administration permission required.');$add=$this->db->prepare("INSERT INTO chat_members(conversation_id,user_id,role,status) VALUES(?,?,'member','active') ON DUPLICATE KEY UPDATE status='active'");$count=0;foreach(array_unique(array_map('intval',$ids)) as $id){if($id<1)continue;$add->bind_param('ii',$c,$id);$add->execute();$count++;}return ['added'=>$count];}
 function adminConversations($search=''){$like='%'.trim($search).'%';$s=$this->db->prepare("SELECT c.id,c.type,COALESCE(c.name,ctx.context_title,'Conversation') name,c.status,c.created_at,c.last_message_at,u.nick_name created_by_name,COUNT(DISTINCT cm.user_id) member_count,COUNT(DISTINCT m.id) message_count,ctx.context_type,ctx.context_id FROM chat_conversations c JOIN users u ON u.id=c.created_by LEFT JOIN chat_members cm ON cm.conversation_id=c.id AND cm.status='active' LEFT JOIN chat_conversation_messages m ON m.conversation_id=c.id LEFT JOIN chat_contexts ctx ON ctx.conversation_id=c.id WHERE COALESCE(c.name,ctx.context_title,'') LIKE ? GROUP BY c.id ORDER BY c.last_message_at DESC,c.id DESC LIMIT 200");$s->bind_param('s',$like);$s->execute();return $s->get_result()->fetch_all(MYSQLI_ASSOC);} function deleteConversationForMe($u,$c){$this->member($u,$c);$s=$this->db->prepare('UPDATE chat_members SET archived_at=NOW(),last_read_at=NOW() WHERE conversation_id=? AND user_id=?');$s->bind_param('ii',$c,$u);$s->execute();return true;}
 function deleteEmptyDiscussion($u,$c){$this->member($u,$c);$q=$this->db->prepare("SELECT type,(SELECT COUNT(*) FROM chat_conversation_messages WHERE conversation_id=c.id) message_count FROM chat_conversations c WHERE c.id=?");$q->bind_param('i',$c);$q->execute();$row=$q->get_result()->fetch_assoc();if(!$row||$row['type']!=='contextual'||(int)$row['message_count']>0)return ['deleted'=>false];$d=$this->db->prepare('DELETE FROM chat_conversations WHERE id=?');$d->bind_param('i',$c);$d->execute();return ['deleted'=>$d->affected_rows>0];} function exitGroup($u,$c){$me=$this->member($u,$c);$q=$this->db->prepare("SELECT c.type,(SELECT COUNT(*) FROM chat_members WHERE conversation_id=c.id AND status='active') member_count FROM chat_conversations c WHERE c.id=?");$q->bind_param('i',$c);$q->execute();$row=$q->get_result()->fetch_assoc();if(!$row||$row['type']!=='group')throw new DomainException('Only group conversations can be exited.');if($me['role']==='owner'&&(int)$row['member_count']>1)throw new DomainException('Assign another owner before leaving this group.');$s=$this->db->prepare("UPDATE chat_members SET status='left',archived_at=NOW() WHERE conversation_id=? AND user_id=?");$s->bind_param('ii',$c,$u);$s->execute();return true;}
 function adminDeleteConversation($c){$q=$this->db->prepare('SELECT type FROM chat_conversations WHERE id=?');$q->bind_param('i',$c);$q->execute();$row=$q->get_result()->fetch_assoc();if(!$row)throw new InvalidArgumentException('Conversation not found.');if(!in_array($row['type'],['group','contextual'],true))throw new DomainException('Only group chats and discussions can be permanently deleted.');$d=$this->db->prepare('DELETE FROM chat_conversations WHERE id=?');$d->bind_param('i',$c);$d->execute();return ['deleted'=>true,'id'=>$c];}
 function setMemberRole($u,$c,$target,$role){$me=$this->member($u,$c);if($me['role']!=='owner')throw new DomainException('Only the conversation owner can change administrator permissions.');if(!in_array($role,['admin','member'],true))throw new InvalidArgumentException('Member role must be admin or member.');if($target===$u)throw new DomainException('The owner role cannot be changed.');$q=$this->db->prepare("SELECT c.type,cm.role FROM chat_conversations c JOIN chat_members cm ON cm.conversation_id=c.id AND cm.user_id=? AND cm.status='active' WHERE c.id=?");$q->bind_param('ii',$target,$c);$q->execute();$row=$q->get_result()->fetch_assoc();if(!$row)throw new InvalidArgumentException('Active participant not found.');if(!in_array($row['type'],['group','contextual'],true))throw new DomainException('Administrator permissions apply only to groups and discussions.');if($row['role']==='owner')throw new DomainException('The owner role cannot be changed.');$s=$this->db->prepare('UPDATE chat_members SET role=? WHERE conversation_id=? AND user_id=?');$s->bind_param('sii',$role,$c,$target);$s->execute();return ['user_id'=>$target,'role'=>$role];} function removeMember($u,$c,$target){$me=$this->member($u,$c);if(!in_array($me['role'],['owner','admin'],true))throw new DomainException('Group administration permission required.');if($target===$u)throw new DomainException('Use Exit group to leave.');$q=$this->db->prepare('SELECT role FROM chat_members WHERE conversation_id=? AND user_id=? AND status=\'active\'');$q->bind_param('ii',$c,$target);$q->execute();$member=$q->get_result()->fetch_assoc();if(!$member)throw new DomainException('Member not found.');if($member['role']==='owner'||($me['role']!=='owner'&&$member['role']==='admin'))throw new DomainException('You cannot remove this group administrator.');$s=$this->db->prepare("UPDATE chat_members SET status='removed',archived_at=NOW() WHERE conversation_id=? AND user_id=?");$s->bind_param('ii',$c,$target);$s->execute();return true;}}
